"""Changelog and version files from Conventional Commit messages. See task.md."""

from __future__ import annotations

import os
import re

_HEADER_RE = re.compile(r"^([a-z]+)(\(([^()]*)\))?(!)?:(.*)$")
_VERSION_RE = re.compile(r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$")

_SECTIONS = [
    ("breaking", "Breaking changes"),
    ("feat", "Features"),
    ("fix", "Fixes"),
    ("perf", "Performance"),
]


class CommitError(ValueError):
    """Raised when `previous_version` is not a valid `X.Y.Z` version."""


def _parse_commit(commit: str):
    subject, _, body = commit.partition("\n\n")
    subject = subject.strip()
    if "\n" in subject:
        return None
    match = _HEADER_RE.match(subject)
    if not match:
        return None
    ctype, _, scope, bang, description = match.groups()
    description = description.strip()
    if not description:
        return None
    scope = scope.strip() if scope is not None else ""
    scope = scope or None

    breaking = bool(bang)
    if not breaking and body:
        for line in body.split("\n"):
            line = line.strip()
            if line.startswith("BREAKING CHANGE:") or line.startswith("BREAKING-CHANGE:"):
                breaking = True
                break

    return {"type": ctype, "scope": scope, "description": description, "breaking": breaking}


def build(commits: list[str], previous_version: str, out_dir: str) -> None:
    """Write `<out_dir>/CHANGELOG.md` and `<out_dir>/version.txt`."""
    version_match = _VERSION_RE.match(previous_version)
    if not version_match:
        raise CommitError(f"invalid version: {previous_version!r}")
    major, minor, patch = (int(part) for part in version_match.groups())

    parsed = [p for p in (_parse_commit(c) for c in commits) if p is not None]

    has_breaking = any(p["breaking"] for p in parsed)
    has_feat = any(p["type"] == "feat" and not p["breaking"] for p in parsed)
    has_fix_or_perf = any(
        p["type"] in ("fix", "perf") and not p["breaking"] for p in parsed
    )

    if has_breaking:
        major, minor, patch = major + 1, 0, 0
    elif has_feat:
        minor, patch = minor + 1, 0
    elif has_fix_or_perf:
        patch += 1

    new_version = f"{major}.{minor}.{patch}"

    entries = {key: set() for key, _ in _SECTIONS}
    for p in parsed:
        if p["breaking"]:
            key = "breaking"
        elif p["type"] in ("feat", "fix", "perf"):
            key = p["type"]
        else:
            continue
        if p["scope"]:
            line = f"- **{p['scope']}**: {p['description']}"
        else:
            line = f"- {p['description']}"
        entries[key].add((p["scope"] or "", p["description"], line))

    lines = [f"## {new_version}\n"]
    for key, heading in _SECTIONS:
        items = entries[key]
        if not items:
            continue
        sorted_items = sorted(
            items, key=lambda t: (t[0] == "", t[0], t[1])
        )
        lines.append("\n")
        lines.append(f"### {heading}\n")
        lines.append("\n")
        for _, _, line in sorted_items:
            lines.append(f"{line}\n")

    os.makedirs(out_dir, exist_ok=True)
    with open(os.path.join(out_dir, "CHANGELOG.md"), "w", encoding="utf-8") as f:
        f.write("".join(lines))
    with open(os.path.join(out_dir, "version.txt"), "w", encoding="utf-8") as f:
        f.write(f"{new_version}\n")
